return ['domain'=>'tranzly','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'nl_NL','project-id-version'=>'tranzly','pot-creation-date'=>'2026-09-26T14:03:23+00:00','po-revision-date'=>'2026-09-26T14:03:23+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Tranzly'=>'Tranzly','https://zinndigital.com/wordpress-plugins/tranzly'=>'https://zinndigital.com/wordpress-plugins/tranzly','Multilingual WordPress, one post per language: linked translations of posts, pages, categories, media text, widgets and the site title, with your old Tranzly translations imported.'=>'Meertalige WordPress, één bericht per bericht: gekoppelde vertalingen van berichten, pagina\'s, categorieën, mediatekst, widgets en de sitetitel, waarbij uw oude Tranzly-vertalingen zijn geïmporteerd.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'AI-aanbieders','The makers of ChatGPT. A good all-rounder.'=>'De makers van ChatGPT. Een goede allrounder.','The makers of Claude. Strong at writing and careful reasoning.'=>'De makers van Claude. Sterk in schrijven en zorgvuldig redeneren.','Google\'s Gemini models. Fast and inexpensive.'=>'De Gemini-modellen van Google. Snel en voordelig.','A European AI company with fast, inexpensive models.'=>'Een Europees AI-bedrijf met snelle, goedkope modellen.','Low-cost models that are good at writing and code.'=>'Goedkope modellen die goed zijn in schrijven en programmeren.','One key for models from many different providers.'=>'Eén sleutel voor modellen van heel verschillende aanbieders.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Elke service die werkt zoals de API van OpenAI, inclusief een model dat op uw eigen computer of server draait.','General (used when nothing more specific is set)'=>'Algemeen (wordt gebruikt wanneer er niets specifiekers is ingesteld)','Writing and rewriting'=>'Schrijven en herschrijven','Translation'=>'Vertaling','Code and CSS'=>'Code en CSS','Sorry, you are not allowed to access this page.'=>'Het spijt ons, u heeft geen toegang tot deze pagina.','These settings are shared by every plugin that uses them: %s.'=>'Deze instellingen worden gedeeld door elke plug-in die ze gebruikt: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Uw sleutels worden versleuteld in de database van deze site en worden alleen verzonden naar de door u gekozen provider — nooit naar ons.','Step 1 of 2: choose an AI provider'=>'Stap 1 van 2: kies een AI-provider','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'U brengt uw eigen sleutel mee, dus u betaalt de provider rechtstreeks voor wat u gebruikt. Weet u het niet zeker? Elk van deze opties werkt goed; u kunt er later meer toevoegen.','Next'=>'Volgende','Step 2 of 2: connect %s'=>'Stap 2 van 2: verbind %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Vul het adres in van uw OpenAI-compatibele service, eindigend op /v1. Een sleutel is alleen nodig als de service hierom vraagt.','Open %s and sign in (or create a free account).'=>'Open %s en meld u aan (of maak een gratis account aan).','the %s API keys page'=>'de %s API-sleutels pagina','Create a new key and copy it.'=>'Maak een nieuwe sleutel aan en kopieer deze.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Plak het hieronder en druk op "Opslaan en testen". We sturen één klein verzoek om te controleren of het werkt.','Most providers need a little credit on the account before a key works: %s.'=>'De meesteproviders hebben een klein tegoed op het account nodig voordat een sleutel werkt: %s.','add credit'=>'tegoed toevoegen','← Choose a different provider'=>'← Kies een andere provider','Address'=>'Adres','Saved key ends in …%s — paste a new one to replace it'=>'Opgeslagen sleutel eindigt op …%s — plak een nieuwe om deze te vervangen','Key (optional)'=>'Sleutel (optioneel)','API key'=>'API-sleutel','Save and test'=>'Opslaan en testen','Providers'=>'Providers','Provider'=>'Provider','Status'=>'Status','Key'=>'Sleutel','Get a key'=>'Sleutel ophalen','Test'=>'Test','Remove'=>'Verwijderen','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Opgeslagen met een nieuwere pluginversie: werk deze plugin bij of voer de sleutel opnieuw in.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'De opgeslagen sleutel kan niet meer worden geopend (de beveiligingssleutels van de site zijn gewijzigd). Voer deze opnieuw in.','Not connected'=>'Niet verbonden','Connected — last test passed %s'=>'Verbonden — laatste test geslaagd %s','Last test failed: %s'=>'Laatste test mislukt: %s','Connected — not tested yet'=>'Verbonden — nog niet getest','Which model to use'=>'Welk model te gebruiken','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ markeert onze aanbeveling voor die taak. De lijst bevat elk model dat uw sleutel kan gebruiken, live uitgelezen bij de provider.','— Recommended for the provider —'=>'— Aanbevolen voor deprovider —','Save models'=>'Modellen opslaan','Refresh the model lists from the providers'=>'De modellijsten bij de providers vernieuwen','best quality'=>'beste kwaliteit','lowest cost'=>'laagste kosten','fastest'=>'snelste','Add a model yourself'=>'Voeg zelf een model toe','A model came out today? Paste its exact name to use it straight away.'=>'Is er vandaag een model uitgebracht? Plak de exacte naam om het direct te gebruiken.','Model name'=>'Modelnaam','Add model'=>'Model toevoegen','Recommended models list'=>'Lijst met aanbevolen modellen','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'De lijst met aanbevolen modellen kon niet worden geverifieerd, dus er worden geen aanbevelingen weergegeven. Installeer de plug-in opnieuw of schakel hieronder dagelijkse updates in.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'De gebruikte lijst is gepubliceerd op %s. Elke plug-update levert een nieuwe op.','Also check Zinn Digital® once a day for an updated list.'=>'Controleer ook eenmaal per dag Zinn Digital® voor een bijgewerkte lijst.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Er wordt slechts een eenvoudig downloadverzoek verzonden: geen sleutel, geen siteadres, niets over uw inhoud. De lijst is ondertekend en een lijst die de handtekeningcontrole niet doorstaat, wordt genegeerd.','Last checked %1$s: %2$s.'=>'Laatst gecontroleerd op %1$s: %2$s.','Save, and check now if turned on'=>'Opslaan en nu controleren indien ingeschakeld','a newer list was installed'=>'een nieuwere lijst is geïnstalleerd','already up to date'=>'reeds up-to-date','the download failed the signature check and was ignored'=>'de download is niet door de handtekeningcontrole gekomen en is genegeerd','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital® is niet bereikbaar; de huidige lijst blijft in gebruik','turned off'=>'uitgeschakeld','Open'=>'Open','Check their status page'=>'Controleer hun statuspagina','Open your billing page'=>'Open uw facturatiepagina','Open your API keys page'=>'Open uw API-sleutelpagina','Open the AI settings'=>'Open de AI-instellingen','Sorry, you are not allowed to do that.'=>'Het spijt me, u bent niet bevoegd om dat te doen.','Unknown provider.'=>'Onbekende provider.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Voer het adres van uw service in, bijvoorbeeld http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'Dat lijkt geen API-sleutel te zijn. Kopieer deze opnieuw, zonder spaties.','Paste your API key first.'=>'Plak eerst uw API-sleutel.','Key removed.'=>'Sleutel verwijderd.','Models saved.'=>'Modellen opgeslagen.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Voer de exacte naam van het model in, bijvoorbeeld zoals vermeld in de documentatie van de provider.','Added %s. Choose it under "Which model to use".'=>'%s toegevoegd. Kies dit onder "Welk model te gebruiken".','Model removed.'=>'Model verwijderd.','Daily updates are off. The list that came with the plugin is used.'=>'Dagelijkse updates zijn uitgeschakeld. De lijst die bij de plugin werd geleverd, wordt gebruikt.','Checked: %s.'=>'Gecontroleerd: %s.','Model lists refreshed.'=>'Modellijsten vernieuwd.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Uw AI-sleutel is opgeslagen door een nieuwere versie van een van uw plug-ins. Werk deze plug-in bij of voer de sleutel opnieuw in bij de AI-instellingen.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Uw opgeslagen AI-sleutel kan niet meer worden geopend (de beveiligingssleutels van de site zijn gewijzigd). Voer deze opnieuw in bij de AI-instellingen.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'AI is nog niet ingesteld. Voeg een sleutel toe voor een AI-provider in de AI-instellingen.','No model is chosen for this task. Pick one in the AI settings.'=>'Er is geen model geselecteerd voor deze taak. Kies er een in de AI-instellingen.','That AI provider is not supported by this version of the plugin.'=>'Die AI-provider wordt niet ondersteund door deze versie van de plug-in.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Deze website kon uw AI-service niet bereiken. Controleer of deze actief is en of het adres bereikbaar is vanaf uw webserver (een service op uw eigen computer is niet bereikbaar vanuit een gehoste site).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Deze site kon %s niet bereiken. Controleer hun statuspagina; als deze online is, blokkeert uw host mogelijk uitgaande verbindingen of is het adres onjuist.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s meldt dat uw account geen tegoed of limiet meer heeft. Voeg tegoed toe of verhoog uw limiet in uw account bij hen en probeer het opnieuw.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s heeft uw sleutel niet geaccepteerd. Deze is mogelijk onjuist ingevoerd, ingetrokken of verlopen. Maak een nieuwe sleutel aan en plak deze hier.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s heeft dit verzoek om uw sleutel geweigerd. De sleutel heeft mogelijk geen toegang tot dit model of deze functie, of uw account moet worden geverifieerd.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Het model "%1$s" is niet beschikbaar bij %2$s voor uw sleutel. Kies een ander model in de AI-instellingen.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Uw %2$s-abonnement bevat het model "%1$s" niet. Kies een ander model in de AI-instellingen of upgrade uw abonnement via hen.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s beperkt de snelheid waarmee uw sleutel verzoeken kan verzenden. Wacht een minuut en probeer het opnieuw, of verhoog uw tarieflimiet bij hen.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s heeft momenteel problemen (een storing of overbelasting aan hun kant). Er is niets mis met uw instellingen. Probeer het over een ogenblik opnieuw.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'De AI-aanvraag is mislukt om een reden die we niet hebben kunnen achterhalen. Probeer het opnieuw; als dit blijft gebeuren, neem dan contact op met de ondersteuning met onderstaande gegevens.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'De AI-aanbieder antwoordde in een indeling die deze plug-in niet kon lezen. Probeer het opnieuw; kies een ander model of neem contact op met de ondersteuning als dit blijft gebeuren.','Custom (OpenAI-compatible)'=>'Aangepast (OpenAI-compatibel)','Save a key for this provider first.'=>'Sla eerst een sleutel op voor deze provider.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Uw sleutel werkt, maar de provider vermeldt er geen tekstmodel voor. Voeg hieronder zelf een model toe.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Verbonden. %1$s nam op met %2$s. Uw AI-functies zijn klaar voor gebruik.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Uw gebruikersrol is niet toegestaan om AI op deze site te gebruiken. Vraag het aan een beheerder.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Deze website heeft de maandelijkse AI-uitgavenlimiet bereikt. Een beheerder kan deze verhogen in de AI-instellingen.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Deze website heeft de maandelijkse limiet voor AI-verzoeken bereikt. Een beheerder kan deze verhogen in de AI-instellingen.','Usage and cost'=>'Gebruik en kosten','The log, limits and role permissions apply to AI used through: %s.'=>'Het logboek, de limieten en de rolmachtigingen zijn van toepassing op AI die wordt gebruikt via: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Kosten zijn bij benadering en berekend op basis van gepubliceerde prijzen; een model waarvan geen prijs bekend is, telt als nul.','This month: %1$s requests, about %2$s.'=>'Deze maand: %1$s aanvragen, ongeveer %2$s.','When'=>'Wanneer','Who'=>'Wie','Used for'=>'Gebruikt voor','Model'=>'Model','Tokens in / out'=>'Tokens in / uit','About'=>'Over','Result'=>'Resultaat','No AI requests have been made yet.'=>'Er zijn nog geen AI-verzoeken gedaan.','Done'=>'Klaar','Limits and permissions'=>'Limieten en rechten','Monthly spending limit (US dollars)'=>'Maandelijkse bestedingslimiet (US dollars)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Laat leeg voor geen limiet. AI stopt voor de rest van de maand zodra de geschatte kosten dit bereiken.','Monthly request limit'=>'Maandelijkse aanvraaglimiet','Leave empty for no limit.'=>'Laat leeg voor geen limiet.','Who may use AI'=>'Wie AI mag gebruiken','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Vink niets aan zodat iedereen die de functies van de plugin kan gebruiken, AI kan gebruiken. Beheerders kunnen dit altijd gebruiken.','Save limits and permissions'=>'Limieten en rechten opslaan','Limits and permissions saved.'=>'Limieten en machtigingen opgeslagen.','That language is not one of this site\'s languages.'=>'Die taal is geen van de talen van deze site.','A translation must be the same kind of content as the original.'=>'Een vertaling moet hetzelfde soort inhoud zijn als het origineel.','Choose one of the site\'s other languages.'=>'Kies een van de andere talen van de website.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'De scripts van het beheerscherm ontbreken in deze kopie van de plug-in. Installeer deze opnieuw vanuit een vrijgegeven pakket.','This screen needs JavaScript.'=>'Voor dit scherm is JavaScript vereist.','Choose a language'=>'Kies een taal','Upgrade'=>'Upgraden','Pricing'=>'Prijzen','Start Trial'=>'Proefperiode starten','Account'=>'Account','Contact Us'=>'Contact opnemen','Affiliation'=>'Affiliatie','the kind of softwarePlugin'=>'Plugin','greetingHey %s,'=>'Hoi %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Meld u aan om e-mailmeldingen te ontvangen voor beveiligings- en functie-updates, educatief materiaal en af en toe een aanbieding, en om wat basisinformatie over uw WordPress-omgeving te delen. Dit helpt ons om de %s beter compatibel te maken met uw website en beter te laten aansluiten bij wat u ermee wilt bereiken.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Meld u aan om e-mailmeldingen te ontvangen voor beveiligings- en functie-updates, educatieve inhoud en af en toe een aanbieding, en om wat basisinformatie over de WordPress-omgeving te delen.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Als u dit overslaat, is dat geen probleem! %1$s blijft gewoon goed werken.','Allow & Continue'=>'Toestaan en doorgaan','verbSkip'=>'Overslaan','Skipping, please wait'=>'Wordt overgeslagen, een ogenblik geduld','Continue'=>'Doorgaan','Please wait'=>'Even geduld alstublieft','as activating pluginActivating'=>'Activeren','This will allow %s to'=>'Hiermee kan %s','Privacy Policy'=>'Privacybeleid','Terms of Service'=>'Algemene voorwaarden','License Agreement'=>'Licentieovereenkomst','Have a license key?'=>'Beschikt u over een licentiesleutel?','Activate License'=>'Licentie activeren','View Basic Profile Info'=>'Basisinformatie van profiel weergeven','Your WordPress user\'s: first & last name, and email address'=>'Uw WordPress-gebruiker: voor- en achternaam en e-mailadres','View Basic Website Info'=>'Bekijk basiswebsite-info','Homepage URL & title, WP & PHP versions, and site language'=>'Homepage-url en -titel, WP- en PHP-versies en sitetaal','View Basic %s Info'=>'Basisinfo voor %s bekijken','Current %s & SDK versions, and if active or uninstalled'=>'Huidige %s- en SDK-versies, en of ze actief of verwijderd zijn','Newsletter'=>'Nieuwsbrief','Updates, announcements, marketing, no spam'=>'Updates, aankondigingen, marketing, geen spam','View Diagnostic Info'=>'Diagnostische informatie weergeven','WordPress & PHP versions, site language & title'=>'WordPress- en PHP-versies, sitetaal en -titel','View Plugins & Themes List'=>'Lijst met plugins en thema\'s bekijken','Names, slugs, versions, and if active or not'=>'Namen, slugs, versies en of ze actief zijn of niet','optional'=>'optioneel','Never miss an important update'=>'Mis nooit meer een belangrijke update','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'We hebben deze opt-in geïntroduceerd zodat u nooit een belangrijke update hoeft te missen en ons kunt helpen de %s beter compatibel te maken met uw website en beter in staat te stellen om te doen wat u ervan nodig hebt.','Thank you for updating to %1$s v%2$s!'=>'Bedankt voor de update naar %1$s v%2$s!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Het voorvoegsel moet uit 1 tot 8 kleine letters of cijfers bestaan, beginnen met een letter en mag niet de naam van de plugin zijn.','"%s" is not a language code. Use a WordPress locale such as fr_FR or de_DE.'=>'"%s" is geen taalcode. Gebruik een WordPress-landinstelling zoals fr_FR of de_DE.','List at least one language.'=>'Geef ten minste één taal op.','You are not allowed to translate this item.'=>'Het is niet toegestaan om dit item te vertalen.','This item already has a version in that language.'=>'Dit item heeft al een versie in die taal.','That translation engine is not available on this site.'=>'Die vertaalengine is niet beschikbaar op deze site.','Different engines per language, automatic fallback and spending caps are Tranzly Pro features.'=>'Verschillende engines per taal, automatische terugval en uitgavenlimieten zijn functies van Tranzly Pro.','Each language must be one of the site\'s languages, with an available engine.'=>'Elke taal moet een van de talen van de site zijn, waarvoor een beschikbare engine is.','The fallback list may only name available engines.'=>'De terugval-lijst mag alleen beschikbare engines bevatten.','A monthly cap is an amount in US dollars, zero or more, for an available engine.'=>'Een maandelijks limiet is een bedrag in US dollars, nul of meer, voor een beschikbare engine.','Preferred translations and tone per language are Tranzly Pro features. The do-not-translate list is free.'=>'Voorkeursvertalingen en toon per taal zijn Tranzly Pro-functies. De lijst met niet-te-vertalen termen is gratis.','Glossary entries must be grouped by one of the site\'s languages.'=>'Woordenlijstitems moeten worden gegroepeerd op een van de talen van de site.','Tone is set per site language: formality default, more or less, plus optional instructions.'=>'De toon wordt per sitetaal ingesteld: de standaardformaliteit, min of meer, plus optionele instructies.','The value for %s is not one of the allowed choices.'=>'De waarde voor %s behoort niet tot de toegestane keuzes.','The background queue is not available on this site.'=>'De achtergrondwachtrij is niet beschikbaar op deze site.','A translation job runs as the person who starts it, so a user must be signed in.'=>'Een vertaaltaak wordt uitgevoerd als de persoon die deze start, dus een gebruiker moet zijn ingelogd.','There is nothing you are allowed to translate in that selection.'=>'Er is niets in die selectie dat u mag vertalen.','That item is not part of a translation job.'=>'Dat item maakt geen deel uit van een vertaaltaak.','You are not allowed to change that translation.'=>'U bent niet gemachtigd om die vertaling te wijzigen.','This item\'s group already has a %1$s version (#%2$d).'=>'De groep van dit item heeft al een %1$s-versie (#%2$d).','An item cannot be its own translation.'=>'Een item kan niet zijn eigen vertaling zijn.','That item is already a translation of something else. Unlink it first.'=>'Dat item is al een vertaling van iets anders. Ontkoppel het eerst.','The translation link could not be saved.'=>'De vertalingslink kon niet worden opgeslagen.','That text cannot be translated here.'=>'Die tekst kan hier niet worden vertaald.','That media text cannot be translated here.'=>'Die mediatekst kan hier niet worden vertaald.','A translation can be published or kept as a draft.'=>'Een vertaling kan worden gepubliceerd of als concept worden bewaard.','You are not allowed to publish this kind of content.'=>'U bent niet gemachtigd om dit type inhoud te publiceren.','This item is already written in that language.'=>'Dit item is al in die taal geschreven.','This translation was edited by a person (or imported), so it is protected. Unlock it to translate it again.'=>'Deze vertaling is door een mens bewerkt (of geïmporteerd) en is daarom beveiligd. Ontgrendel deze om opnieuw te vertalen.','No translation engine is set up yet. Add a key for one in Tranzly → Engines.'=>'Er is nog geen vertaalmachine ingesteld. Voeg een sleutel hiervoor toe in Tranzly → Engines.','That translation engine is not set up yet: add its key first.'=>'Die vertaalengine is nog niet geconfigureerd: voeg eerst de sleutel toe.','The same text is being translated by another job right now; this item will use that answer.'=>'Dezelfde tekst wordt op dit moment door een andere taak vertaald; dit item zal die vertaling gebruiken.','No translation engine could take this item.'=>'Geen enkele vertaalmachine kon dit item verwerken.','The engine did not return a translation for every part of this item. Nothing was changed.'=>'De engine heeft voor dit item niet voor elk onderdeel een vertaling geretourneerd. Er is niets gewijzigd.','AI model'=>'AI-model','AI model (%1$s %2$s)'=>'AI-model (%1$s %2$s)','%s is having problems right now. Try again shortly, or use another engine.'=>'%s ondervindt momenteel problemen. Probeer het over een ogenblik opnieuw of gebruik een andere engine.','Your site could not reach %s. Check that it can make outgoing connections, then try again.'=>'Uw site kan %s niet bereiken. Controleer of deze uitgaande verbindingen tot stand kan brengen en probeer het opnieuw.','%s did not accept your API key. Check the key in Tranzly → Engines.'=>'%s heeft uw API-sleutel niet geaccepteerd. Controleer de sleutel in Tranzly → Engines.','Your %s account has used up its quota or balance. Top it up with them, or use another engine.'=>'Uw %s-account heeft de limiet of het saldo verbruikt. Waardeer dit aan of gebruik een andere engine.','%s asked us to slow down. It will be tried again automatically.'=>'%s heeft ons gevraagd het rustiger aan te doen. Het wordt automatisch opnieuw geprobeerd.','This text is too long for %s in one go. Split the content, or use another engine.'=>'Deze tekst is te lang voor %s in één keer. Splits de inhoud of gebruik een andere engine.','%s refused to translate this content. Try another engine, or translate it by hand.'=>'%s weigerde deze inhoud te vertalen. Probeer een andere engine of vertaal het handmatig.','%s does not translate this language. Choose another engine for it.'=>'%s vertaalt deze taal niet. Kies er een andere engine voor.','This month\'s spending cap for %s is reached, so nothing more was sent to it. Raise the cap in Tranzly → Engines, or wait until next month.'=>'Het bestedingslimiet van deze maand voor %s is bereikt, dus er is niets meer naar verzonden. Verhoog het limiet in Tranzly → Engines, of wacht tot volgende maand.','The translation with %s failed for a reason Tranzly could not identify. The details are below.'=>'De vertaling met %s is mislukt om een reden die Tranzly niet kon identificeren. De details staan hieronder.','An engine id must be lowercase letters, digits and hyphens.'=>'Een engine-ID mag alleen uit kleine letters, cijfers en koppeltekens bestaan.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Ontworpen door Neil Lock, CEO van Zinn Digital® Ltd','Version %s'=>'Versie %s','Tranzly website'=>'Tranzly-website','Zinn Digital® website'=>'Zinn Digital®-website','Settings saved.'=>'Instellingen opgeslagen.','See the Pro plans and pricing'=>'Bekijk de Pro-abonnementen en prijzen','Languages'=>'Talen','The first language is the one your content is written in. Visitors switch with the language switcher block.'=>'De eerste taal is de taal waarin uw inhoud is geschreven. Bezoekers schakelen over met het taalwisselaarblok.','(default)'=>'(standaard)','Locale code'=>'Landalcode','For example fr_FR'=>'Bijvoorbeeld fr_FR','Name (optional)'=>'Naam (optioneel)','For example Français'=>'Bijvoorbeeld Français','Add language'=>'Taal toevoegen','Front-end output'=>'Frontend-uitvoer','Class name prefix'=>'Klassennaamprefix','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Elke klassennaam die de plug-in op uw pagina\'s weergeeft, begint met dit voorvoegsel, zodat de pagina\'s niet onthullen welke plug-in ze heeft gemaakt. 1 tot 8 kleine letters of cijfers, beginnend met een letter.','Beta updates'=>'Bèta-updates','This site receives beta versions as updates.'=>'Deze site ontvangt bètaversies als updates.','This site receives stable versions only.'=>'Deze site ontvangt alleen stabiele versies.','Change this on the Account page'=>'Wijzig dit op de accountpagina','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Bètaversies worden aangeboden aan gelicentieerde Pro-installaties die aan hun account zijn gekoppeld. Zodra deze zijn gekoppeld, kunt u deelnemen via de accountpagina.','Save settings'=>'Instellingen opslaan','First engine that is set up'=>'Eerste engine die wordt ingesteld','Key saved. It is stored encrypted and never shown again.'=>'Sleutel opgeslagen. Deze wordt versleuteld opgeslagen en nooit meer getoond.','Engine settings saved.'=>'Engine-instellingen opgeslagen.','Glossary saved.'=>'Glossarium opgeslagen.','Your keys'=>'Uw sleutels','Tranzly calls the translation services with your own account. Keys are stored encrypted in your database and are only ever sent to the service they belong to. AI model keys are set in the AI settings.'=>'Tranzly roept de vertaaldiensten aan met uw eigen account. Sleutels worden versleuteld opgeslagen in uw database en worden uitsluitend verzonden naar de dienst waar ze bij horen. Sleutels voor AI-modellen worden ingesteld in de AI-instellingen.','%s API key'=>'%s API-sleutel','Saved: %s. Enter a new key to replace it, or save an empty field to remove it.'=>'Opgeslagen: %s. Voer een nieuwe sleutel in om deze te vervangen, of sla een leeg veld op om deze te verwijderen.','No key saved.'=>'Geen sleutel opgeslagen.','Azure region (leave empty for a global resource)'=>'Azure-regio (leeg laten voor een globaal resource)','Save key'=>'Sleutel opslaan','Check my DeepL usage'=>'Mijn DeepL-gebruik controleren','%1$s of %2$s characters used this billing period.'=>'%1$s van de %2$s tekens gebruikt in deze factureringsperiode.','Which engine translates'=>'Welke engine vertaalt','No engine is set up yet. Save a key above (or set up an AI model) to start translating.'=>'Er is nog geen engine ingesteld. Sla hierboven een sleutel op (of stel een AI-model in) om te beginnen met vertalen.','Default engine'=>'Standaard-engine','A different engine per language, automatic fallback and monthly spending caps are Tranzly Pro features.'=>'Een andere engine per taal, automatische terugval en maandelijkse uitgavenlimieten zijn Tranzly Pro-functies.','Engine for %s'=>'Engine voor %s','The default engine'=>'De standaard-engine','If an engine fails or reaches a limit, try these next, in this order'=>'Als een engine uitvalt of een limiet bereikt, probeer dan de volgende stappen in deze volgorde','Monthly spending caps'=>'Maandelijkse uitgavenlimieten','When an engine reaches its cap, nothing more is sent to it until next month and the failed-translation report says why. Leave empty for no cap.'=>'Wanneer een engine zijn limiet bereikt, wordt er tot volgende maand niets meer naar verzonden en geeft het rapport met mislukte vertalingen de reden hiervoor. Laat leeg om geen limiet in te stellen.','%1$s (spent this month: $%2$s)'=>'%1$s (deze maand uitgegeven: $%2$s)','Save caps'=>'Instellingen opslaan','Glossary and words never translated'=>'Woordenlijst en woorden die nooit worden vertaald','Never translate these words (one per line)'=>'Vertaal deze woorden nooit (één per regel)','Brand and product names stay exactly as they are, with every engine.'=>'Merk- en productnamen blijven bij elke engine exact zoals ze zijn.','Preferred translations and tone per language are Tranzly Pro features.'=>'Voorkeursvertalingen en toon per taal zijn Tranzly Pro-functies.','Preferred translations (one per line: term = translation)'=>'Voorkurke vertalingen (één per regel: term = vertaling)','Formality'=>'Formaliteit','Default'=>'Standaard','Formal'=>'Formeel','Informal'=>'Informeel','Style instructions (audience, brand voice)'=>'Stijlinstructies (doelgroep, merkstem)','Save glossary'=>'Woordenlijst opslaan','Job started with %d translations to do. It runs in the background: you can close this page.'=>'Taak gestart met %d uit te voeren vertalingen. Deze wordt op de achtergrond uitgevoerd: u kunt deze pagina sluiten.','Queued again.'=>'Opnieuw in de wachtrij.','Running'=>'Actief','Finished'=>'Voltooid','Cancelled'=>'Geannuleerd','Translate in the background'=>'Op de achtergrond vertalen','Set up a translation engine in the Engines tab first.'=>'Stel eerst een vertaalengine in op het tabblad Engines.','Translate every'=>'Vertaal alles','Into'=>'Naar','With'=>'Met','Each language’s own engine'=>'Elke taal heeft zijn eigen engine','Publish the translations (otherwise they are saved as drafts)'=>'Publiceer de vertalingen (anders worden ze als concept opgeslagen)','Estimate the cost'=>'Schat de kosten','%1$d posts, %2$s characters. The price for this engine is not known in advance.'=>'%1$d berichten, %2$s tekens. De prijs voor deze engine is niet vooraf bekend.','%1$d posts, %2$s characters: about $%3$s on your own account.'=>'%1$d artikelen, %2$s tekens: ongeveer $%3$s op uw eigen account.','Start translating'=>'Start met vertalen','Jobs'=>'Taken','No translation jobs yet.'=>'Nog geen vertaaltaken.','Job %1$d — %2$s'=>'Taak %1$d — %2$s','%1$d of %2$d translated, %3$d failed, %4$d skipped (protected or already in that language)'=>'%1$d van %2$d vertaald, %3$d mislukt, %4$d overgeslagen (beschermd of al in die taal)','Stop this job'=>'Deze taak stoppen','See what failed and why'=>'Bekijk wat er misging en waarom','Content'=>'Inhoud','Language'=>'Taal','What went wrong'=>'Wat is er misgegaan','Fix it'=>'Los het op','Details'=>'Details','Retry with'=>'Opnieuw proberen met','The same engine'=>'Dezelfde engine','Retry'=>'Opnieuw proberen','Translate by hand'=>'Handmatig vertalen','Languages and settings'=>'Talen en instellingen','Engines'=>'Engines','Translation jobs'=>'Vertalingenbeheertaken','Add a second language under Tranzly in the admin menu, and the switcher appears here.'=>'Voeg een tweede taal toe onder Tranzly in het beheermenu en de schakelaar verschijnt hier.','Switcher'=>'Wisselaar','Accessible label'=>'Toegankelijkheidslabel','block titleLanguage switcher'=>'Taalwisselaar','block descriptionLinks to this page in each of the site\'s languages. It renders nothing until two or more languages are listed.'=>'Links naar deze pagina in elke taal van de website. Dit geeft niets weer totdat er twee of meer talen worden vermeld.','block keywordlanguage'=>'Taal','block keywordswitcher'=>'omschakelaar','block keywordtranslation'=>'vertaling']];